#include <stdio.h>
#include <stdlib.h>
#include <limits.h>
#include <stdbool.h>

static bool mul_overflow_ll(long long a, long long b, long long *out) {
    if (a == 0 || b == 0) {
        *out = 0;
        return false;
    }
    if (a > 0) {
        if (b > 0) {
            if (a > LLONG_MAX / b) return true;
        } else {
            if (b < LLONG_MIN / a) return true;
        }
    } else {
        if (b > 0) {
            if (a < LLONG_MIN / b) return true;
        } else {
            if (a < LLONG_MAX / b) return true;
        }
    }
    *out = a * b;
    return false;
}

static long long gcd_ll(long long a, long long b) {
    while (b != 0) {
        long long r = a % b;
        a = b;
        b = r;
    }
    return a;
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        puts("USAGE");
        return 0;
    }
    char *end1, *end2;
    long long a = strtoll(argv[1], &end1, 10);
    long long b = strtoll(argv[2], &end2, 10);
    if (end1 == argv[1] || *end1 != '\0' || end2 == argv[2] || *end2 != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    if (a == LLONG_MIN || b == LLONG_MIN) {
        puts("OVERFLOW");
        return 0;
    }
    long long abs_a = a < 0 ? -a : a;
    long long abs_b = b < 0 ? -b : b;
    if (abs_a > 1000000LL || abs_b > 1000000LL) {
        puts("OUT_OF_RANGE");
        return 0;
    }
    if (abs_a == 0 && abs_b == 0) {
        puts("gcd=0 lcm=0");
        return 0;
    }
    long long g = gcd_ll(abs_a, abs_b);
    long long part = abs_a / g;
    long long lcm;
    if (mul_overflow_ll(part, abs_b, &lcm)) {
        puts("OVERFLOW");
        return 0;
    }
    printf("gcd=%ld lcm=%ld\n", g, lcm);
    return 0;
}
